            ekadashiDiscipline: "Ekadashi favors fasting, prayer, and letting go of excess — traditionally the most spiritually charged day of the fortnight. Keep meals light and skip grains if you're observing the vrat.",
            pushyaAuspicious: "Today's Moon sits in Pushya, considered the most all-round auspicious nakshatra — good for starting almost anything except a wedding. A favorable day to sign documents, start a course, or begin a new routine.",
