            ravivaarVitality: "Ravivaar (Sunday) is ruled by the Sun — a good day for anything that calls for confidence, visibility, or dealing with authority. Physical vitality runs a little higher too, so it's a fine day for exercise or time outdoors.",
            somvaarEmotionalCare: "Somvaar (Monday) is the Moon's own day — gentle on emotional and domestic matters, and traditionally favored for Shiva worship. Good for family time, water rituals, or simply slowing down.",
            pratipadaFreshStart: "Pratipada, the first tithi, favors fresh starts — small first steps taken today tend to build momentum through the fortnight. Good for planning and intentions rather than big, irreversible moves.",
