            tritiyaCelebration: "Tritiya carries a graceful, celebratory energy — favorable for beauty rituals, art, music, and social occasions. A pleasant day to indulge a little.",
            chaturthiObstacles: "Chaturthi is Ganesha's tithi — good for clearing obstacles and starting groundwork on something that's felt stuck. The old caution: avoid glancing at the moon tonight.",
            panchamiLearning: "Panchami favors learning, study, and creative pursuits — a good day to begin a course, pick up an instrument, or open the book you've been putting off.",
            shashthiCourage: "Shashthi brings a disciplined, courageous energy — favorable for fitness, competitive pursuits, and anything that needs a bit of grit to push through.",
            saptamiLeadership: "Saptami, the Sun's own tithi, favors leadership, visibility, and physical vitality — a solid day to put yourself forward or start a fitness routine.",
            ashtamiInnerStrength: "Ashtami, dedicated to Devi, carries an intense, resolute energy — good for facing something difficult head-on, though feelings may run deep. Ground yourself before big conversations.",
            navamiBoldAction: "Navami favors bold, decisive action — the tithi of Durga's fiercest form rewards courage today, though it can also run a little short-tempered. Channel the intensity into a task that needs a push, not into conflict.",
            dashamiResolve: "Dashami, ruled by Dharma, favors justice, resolving disputes, and following through on commitments — a grounded day for anything that needs a fair, clear-headed decision.",
            dwadashiCharity: "Dwadashi favors charity, generosity, and closing out fasts or commitments gracefully — a good day to give something away, literally or figuratively.",
