            purnimaCulmination: "पौर्णिमा गोष्टींना कळस गाठून देते — प्रकल्प पूर्ण करणे, कृतज्ञता व्यक्त करणे आणि जवळच्या माणसांसोबत एकत्र येण्यासाठी चांगला दिवस. भावना नेहमीपेक्षा थोड्या तीव्र असतात, त्यामुळे शक्य असल्यास वादविवाद टाळा.",
