            pushyaAuspicious: "आज चंद्र पुष्य नक्षत्रात आहे, जो सर्वात सर्वांगीण शुभ नक्षत्र मानला जातो — विवाह वगळता जवळजवळ प्रत्येक गोष्ट सुरू करण्यासाठी चांगला. कागदपत्रांवर स्वाक्षरी करणे, अभ्यासक्रम सुरू करणे किंवा नवीन दिनचर्या सुरू करण्यासाठी शुभ दिवस.",
            cautiousNakshatra: "आजच्या नक्षत्राकडे पारंपरिकपणे अगदी नवीन सुरुवातीसाठी थोडी अधिक सावधगिरीने पाहिले जाते. मोठी सुरुवात करण्याऐवजी सुरू असलेले काम पूर्ण करणे, संशोधन करणे किंवा शांतपणे तयारी करणे चांगले.",
            ravivaarVitality: "रविवार सूर्याच्या अधिपत्याखाली आहे — आत्मविश्वास, दृश्यमानता किंवा अधिकारी व्यक्तींशी संबंधित कोणत्याही कामासाठी चांगला दिवस. शारीरिक ऊर्जाही थोडी जास्त असते, त्यामुळे व्यायाम किंवा घराबाहेर वेळ घालवण्यासाठीही योग्य.",
            somvaarEmotionalCare: "सोमवार हा चंद्राचा स्वतःचा दिवस आहे — भावनिक आणि घरगुती बाबींसाठी सौम्य, आणि पारंपरिकपणे शिवपूजेसाठी शुभ मानला जातो. कुटुंबासोबत वेळ घालवणे, जल-विधी किंवा फक्त वेग कमी करण्यासाठी चांगला.",
            pratipadaFreshStart: "प्रतिपदा, पहिली तिथी, नवीन सुरुवातीसाठी शुभ आहे — आज उचललेली छोटी पावले संपूर्ण पंधरवड्यात गती निर्माण करतात. मोठ्या, अपरिवर्तनीय निर्णयांऐवजी नियोजन आणि संकल्पासाठी चांगला दिवस.",
            dwitiyaPartnership: "द्वितीया स्थिर, सहकार्यपूर्ण प्रयत्नांना पाठिंबा देते — भागीदारी, वाटाघाटी आणि संयमाची गरज असलेल्या कोणत्याही कामासाठी चांगला दिवस.",
            tritiyaCelebration: "तृतीयेमध्ये एक सुंदर, उत्सवी ऊर्जा असते — सौंदर्य विधी, कला, संगीत आणि सामाजिक प्रसंगांसाठी शुभ. थोडे लाड करून घेण्यासाठी आल्हाददायक दिवस.",
            chaturthiObstacles: "चतुर्थी ही गणेशाची तिथी आहे — अडथळे दूर करण्यासाठी आणि अडकलेल्या एखाद्या कामाचा पाया घालण्यासाठी चांगली. जुनी सावधगिरी: आज रात्री चंद्राकडे पाहणे टाळा.",
            panchamiLearning: "पंचमी शिकणे, अभ्यास आणि सर्जनशील कामांसाठी शुभ आहे — अभ्यासक्रम सुरू करणे, वाद्य शिकणे किंवा राहून गेलेले पुस्तक उघडण्यासाठी चांगला दिवस.",
            shashthiCourage: "षष्ठी शिस्तबद्ध, धाडसी ऊर्जा घेऊन येते — तंदुरुस्ती, स्पर्धात्मक कामे आणि चिकाटीची गरज असलेल्या कोणत्याही गोष्टीसाठी शुभ.",
            saptamiLeadership: "सप्तमी, सूर्याची स्वतःची तिथी, नेतृत्व, दृश्यमानता आणि शारीरिक ऊर्जेसाठी शुभ आहे — स्वतःला पुढे आणण्यासाठी किंवा तंदुरुस्तीची दिनचर्या सुरू करण्यासाठी भक्कम दिवस.",
            ashtamiInnerStrength: "देवीला समर्पित अष्टमीमध्ये तीव्र, निर्धारी ऊर्जा असते — एखाद्या कठीण गोष्टीला थेट सामोरे जाण्यासाठी चांगली, जरी भावना खोलवर असू शकतात. मोठ्या संभाषणापूर्वी स्वतःला स्थिर करा.",
            navamiBoldAction: "नवमी धाडसी, निर्णायक कृतीसाठी शुभ आहे — दुर्गेच्या सर्वात उग्र रूपाची ही तिथी आज धाडसाचे फळ देते, जरी ती थोडी तापट स्वभावाचीही असू शकते. तीव्रतेला संघर्षाऐवजी गरजेच्या कामात वापरा.",
            dashamiResolve: "धर्माच्या अधिपत्याखालील दशमी न्याय, वाद मिटवणे आणि वचनबद्धता पूर्ण करण्यासाठी शुभ आहे — निष्पक्ष, स्पष्ट निर्णयाची गरज असलेल्या कोणत्याही गोष्टीसाठी स्थिर दिवस.",
            dwadashiCharity: "द्वादशी दान, औदार्य आणि उपवास किंवा वचनबद्धता सुरेखपणे पूर्ण करण्यासाठी शुभ आहे — शाब्दिक किंवा लाक्षणिक अर्थाने काहीतरी दान करण्यासाठी चांगला दिवस.",
            reflectiveWriting: "लेखन, रोजनिशी लिहिणे किंवा शांत चिंतनासाठी चांगला दिवस — शुक्ल त्रयोदशीची सौम्य, वाढती ऊर्जा आत्मशोधाच्या अंतर्गत प्रवासाला पाठबळ देते.",
